""" compute the infix statement"""
def doMath(op: str, op1: int, op2: int) -> int | float {
    if (op == "^") {
        return (op1 ^ op2);
    } elif (op == "*") {
        return (op1 * op2);
    } elif (op == "/") {
        if (op2 == 0) {
            raise ValueError('Cannot divide by zero');
        }
        return (op1 / op2);
    } elif (op == "+") {
        return (op1 + op2);
    } else {
        return (op1 - op2);
    }
}

