"""
    Function tha computes Recall and Precision with exact matches
    """
def compute_exact_R_P[T](final_patterns: dict[str, list[T]], centones_tab: dict[str, list[T]]) -> tuple[float, float] {
    true = 0;
    for tab in final_patterns {
        for centon in centones_tab[tab] {
            check = False;
            for p in final_patterns[tab] {
                if (centon == p) {
                    check = True;
                }
            }
            if check {
                true += 1;
            }
        }
    }
    all_centones = len([x for y in centones_tab.values() for x in y]);
    all_ours = len([x for y in final_patterns.values() for x in y]);
    overall_recall = true / all_centones;
    overall_precision = true / all_ours;
    return (overall_recall, overall_precision);
}

"""Accept a step when using the doubling procedure (Neal 2003)."""
def slice_double_accept(
    xp: float,
    x: float,
    u: float,
    step: float,
    interval: tuple[float, float],
    lnpdf: callable[[float], float],
    pdf_params: tuple[float, ...]
) -> bool {
    (xl, xr) = interval;
    d = False;
    acceptable = True;
    while (xr - xl) > 1.1 * step {
        m = (xl + xr) * 0.5;
        if (x < m and xp >= m) or (x >= m and xp < m) {
            d = True;
        }
        if xp < m {
            xr = m;
        } else {
            xl = m;
        }
        if d and lnpdf(xl, *pdf_params) <= u and lnpdf(xr, *pdf_params) <= u {
            acceptable = False;
            break;
        }
    }
    return acceptable;
}

