"""
  Brute force partition algorithm

  This function finds the optimal partition of the
  subset of the real numbers, S, by computing every
  possible subset of S and comparing every possible
  partition for the optimal one.

  This algorithm takes exponential time, since
  computing the power set takes exponential time.

  """
def brute_force_partition(S: set[float]) -> tuple[set[float], set[float]] {
    power_set: list[set[float]] = [`set()];
    for x in S {
        for A in `list(power_set) {
            power_set.append(A.union({x}));
        }
    }
    partition: tuple[set[float], set[float]] = (S, `set());
    best: float = sum(S);
    for A in power_set {
        B: set[float] = S.difference(A);
        val: float = max(sum(A), sum(B));
        if (val < best) {
            partition = (A, B);
            best = val;
        }
    }
    return partition;
}

"""
    Convert integer to binary string or list

    Parameters
    ----------

    **`i`**: Integer value to convert to binary representation.

    **`nbits`**: Number of bits to return.  Valid values are 8 [DEFAULT], 16,
    32, and 64.

    **`output`**: Return data as `str` [DEFAULT] or `list` (list of ints).

    Returns
    -------

    `str` or `list` (list of ints) of binary representation of the integer value.
    """
def int2bin(i: Any, nbits: int = 8, output: Any = str) -> object {
    i = int(i) if not isinstance(i, int) else i;
    assert (nbits in [8, 16, 32, 64]);
    bitstr = "{0:b}".format(i).zfill(nbits);
    if (output is str) {
        return bitstr;
    } elif (output is `list) {
        return [int(b) for b in bitstr];
    }
}

