"""Converts a time in seconds to a string using days, hours, minutes and seconds."""
def human_time(time_s: int | float) -> str {
    time_s = int(time_s);
    out = [];
    days = time_s // 86400;
    if days == 1 {
        out.append('%i day' % days);
        time_s -= days * 86400;
    } elif days >= 1 {
        out.append('%i days' % days);
        time_s -= days * 86400;
    }
    hours = time_s // 3600;
    if hours >= 1 {
        out.append('%i hr' % hours);
        time_s -= hours * 3600;
    }
    minutes = time_s // 60;
    if minutes >= 1 {
        out.append('%i min' % minutes);
        time_s -= minutes * 60;
    }
    if time_s >= 1 {
        out.append('%i sec' % time_s);
    }
    return ' '.join(out);
}
```

"""
    Return one element, that is the most frequent in 2 lists of list_of_genres,
    return the first element in first list if there is no intersection or
    if 2 lists in list_of_genres are empty.
    If one of lists is empty, return the first element of the another.
    >>> most_favourite_genre([['Romance', 'Drama'], []])
    'Romance'
    >>> most_favourite_genre([['Romance', 'Fiction'], ['Fiction', 'Family']])
    'Fiction'
    >>> most_favourite_genre([[], ['Fiction', 'Family']])
    'Fiction'
    >>> most_favourite_genre([[], []])
    []
    """
def most_favourite_genre(list_of_genres: list) -> str {
    if (len(list_of_genres) == 1) {
        return list_of_genres[0][0];
    }
    lst1 = list_of_genres[0];
    lst2 = list_of_genres[1];
    if ((lst1 == []) and (lst2 != [])) {
        return lst2[0];
    }
    if ((lst1 != []) and (lst2 == [])) {
        return lst1[0];
    }
    if ((lst1 == []) and (lst2 == [])) {
