            2  generates 21, 23
    """
def bfs(x: Any, n: Any, res: list) -> object {
    q = [];
    q.append(x);
    while q {
        p = q.pop(0);
        if (p <= n) {
            res.append(p);
            d = p % 10;
            if (d == 0) {
                q.append(((p * 10) + (d + 1)));
