    for idx in range(len(code)) {
        if (code[idx] == '0') {
            one_letter = 0;
        } else {
            one_letter = decodings[(idx - 1)] if (idx > 0) else 1;
        }
        if ((idx >= 1) and (10 <= int(code[(idx - 1):(idx + 1)]) <= 26)) {
