"""Normalize a path by resolving '.' and '..' path elements."""
def _normalizePath(path: str) -> object {
    if (path == '/') {
        return path;
    }
    new_segments = [];
    prefix = '';
    if path.startswith('/') {
        prefix = '/';
        path = path[1:];
    }
    for segment in path.split('/') {
        if (segment == '.') {
            continue;
        }
        if (segment == '..') {
            new_segments.pop();
            continue;
        }
        if not segment {
            raise ValueError(('path must not contain empty segments: %s' % path));
        }
        new_segments.append(segment);
    }
    return (prefix + '/'.join(new_segments));
}

