def softclip_regions(read_start: int, cigar: list[tuple[int, int]]) -> list[list[int | str]] {
    regions: list[list[int | str]] = [];
    cursor: int = read_start;
    for element in cigar {
        if (element[0] == 4) {
            regions.append([cursor, (cursor + element[1]), 'softclip']);
