    l = l.replace("<sup>", "^{").replace("</sup>", "}");
    l = l.replace("<sub>", "_{").replace("</sub>", "}");
    l = l.replace("<br>", "\n");
    if math {
        l = l.replace("alpha", "\\alpha");
        l = l.replace("beta", "\\beta");
        l = l.replace("sigma", "\\sigma");
    }
