    """Checks whether CP is the codepoint of a CJK character."""
    def _is_chinese_char(cp: int) -> bool {
        if (
            (19968 <= cp <= 40959)
            or (13312 <= cp <= 19903)
            or (131072 <= cp <= 173791)
            or (173824 <= cp <= 177983)
            or (177984 <= cp <= 178207)
            or (178208 <= cp <= 183983)
            or (63744 <= cp <= 64255)
            or (194560 <= cp <= 195103)
        ) {
            return True;
        }
        return False;
    }
    def is_whitespace(c: str) -> bool {
        if (
            (c == " ") or (c == "\t") or (c == "\r") or (c == "\n") or (ord(c) == 8239)
        ) {
            return True;
        }
        return False;
    }
    output: list[str] = [];
    buff = "";
    for char in text {
        cp = ord(char);
        if (_is_chinese_char(cp) or is_whitespace(char)) {
            if (buff != "") {
                output.append(buff);
                buff = "";
            }
            output.append(char);
        } else {
            buff += char;
        }
    }
    if (buff != "") {
        output.append(buff);
    }
