def successors(x: float, y: float, X: float, Y: float) -> object {
    assert ((x <= X) and (y <= Y));
    return {
        (0, (y + x)) if ((y + x) <= Y) else ((x - (Y - y)), (y + (Y - y))): 'X->Y',
        ((x + y), 0) if ((x + y) <= X) else ((x + (X - x)), (y - (X - x))): 'X<-Y',
