""" Rename a function or class in a JavaScript code string.

    Parameters:
        jscode (str): the JavaScript source code
        cur_name (str): the current name
        new_name (str): the name to replace the current name with

    Returns:
        jscode (str): the modified JavaScript source code
    """
def js_rename(jscode: str, cur_name: str, new_name: str) -> object {
    jscode = jscode.replace(
        ('%s = function' % cur_name), ('%s = function' % new_name), 1
    );
    jscode = jscode.replace(('%s.prototype' % cur_name), ('%s.prototype' % new_name));
    jscode = jscode.replace(
        ('_class_name = "%s"' % cur_name), ('_class_name = "%s"' % new_name)
    );
    if ('.' in new_name) {
        jscode = jscode.replace(('var %s;\n' % cur_name), '', 1);
    } else {
        jscode = jscode.replace(('var %s;\n' % cur_name), ('var %s;\n' % new_name), 1);
    }
    return jscode;
}
