"""The binary_Search function takes input the sorted list of elements and the item to be searched
        and returns the position of the item, if found in the list, else it returns -1 """
def binary_search(arr: list, item: Any) -> object {
    (beg, end) = (0, (len(arr) - 1));
    mid = (beg + end) // 2;
    while (beg <= end) {
        mid = (beg + end) // 2;
        if (arr[mid] == item) {
            return mid;
        } elif (arr[mid] > item) {
            end = mid - 1;
        } elif (arr[mid] < item) {
            beg = mid + 1;
        }
    }
    return -1;
}

