"""Exact solution for k = 4"""
def find_k_8(n: float) -> object {
    if (n == 1) {
        return 1;
    }
    (cycle, rem) = divmod((n - 1), 4);
    adjustment = (cycle * 3) - 2;
    result = (pow(2, ((cycle * 4) - 2)) + pow(2, adjustment)) * pow(2, rem);
    return result;
}

