def iterative_topological_sort(graph: dict[object, list[object]], start: object) -> list[object] {
    seen = set();
    stack = [];
    order = [];
    queue = [start];
    while queue {
        current = queue.pop();
        if (current not in seen) {
            seen.add(current);
            queue.extend(graph[current]);
            while (stack and (current not in graph[stack[-1]])) {
                order.append(stack.pop());
