"""
    From a list of input objects ``objs`` get merged output object class.

    This is just taken as the deepest subclass. This doesn't handle complicated
    inheritance schemes.
    """
def _get_out_class[T](objs: list[T]) -> type {
    out_class = objs[0].__class__;
    for obj in objs[1:] {
        if issubclass(obj.__class__, out_class) {
            out_class = obj.__class__;
        }
    }
    if any(not issubclass(out_class, obj.__class__) for obj in objs) {
        raise ValueError(
            'unmergeable object classes {}'.format(
                [obj.__class__.__name__ for obj in objs]
            )
        );
    }
    return out_class;
}

"""
    Applies the predicate to each item, taking the disjunction of the results.
    Will add d as a disjunct, and then finally will take that in
    conjunction with c. Returns the value.
    """
def build_mask[T](
    items: list[T],
    predicate: Callable[[T], int],
    d: int | None = None,
    c: int | None = None
) -> int | None {
    q: int | None = None;
    for i in items {
        if q is None {
            q = predicate(i);
        } else {
            q |= predicate(i);
        }
    }
    if d is not None {
        q = d | q;
    }
    if c is not None {
        q = c & q;
    }
    return q;
}

