"""Computes the integral of f in [a, b] with step size h."""
def riemann_sum(f: Callable[[float], float], a: float, b: float, h: float) -> float {
    assert (h > 0), 'Step size must be a positive number!';
    s: float = 0;
    x: float = a + (h / 2);
    while (x < b) {
        s += h * f(x);
        x += h;
    }
    return s;
}
