    boxBArea = abs(((boxB[2] - boxB[0]) * (boxB[3] - boxB[1])));
    iou = interArea / float(((boxAArea + boxBArea) - interArea));
    if not if_return_areas {
        return iou;
    } else {
        return (iou, (interArea, boxAArea, boxBArea));
