"""
    Add zeros to form 4 continuous characters and add spaces every 4 characters
    :type s: str
    """
def padding_4ch(s: str) -> object {
    n = len(s);
    r = n % 4;
    if (r != 0) {
        k = 4 - r;
        s = (k * '0') + s;
    } else {
        s = s;
    }
    s = s[::-1];
    s = ' '.join(s[i:(i + 4)] for i in range(0, len(s), 4));
    s = s[::-1];
    return s;
}

