"""Parse a "tsv" (tab separated value) string into a list of lists
    of strings (a "table").

    The input text is tabulated using tabulation characters to separate
    the fields of a row and newlines to separate columns.

    The output lines are padded with '' values to ensure that all lines
    have the same length.

    Note that only '\n' is acceptable as the newline character. Other
    special whitespace characters will be left untouched.
    """
def tsv2table(text: str) -> object {
    rows = text.split('\n');
    table_data = [];
    max_len = 0;
    for row in rows {
        line = row.split('\t');
        l = len(line);
        if (l > max_len) {
            max_len = l;
        }
        table_data.append((line, l));
    }
    result = [];
    for (line, l) in table_data {
        if (l < max_len) {
            line += [''] * (max_len - l);
        }
        result.append(line);
    }
    return result;
}

"""
Compute the cumulants from the moments up to order 4
"""
def compute_cumulants(moments: list[float]) -> list[float] {
    assert len(moments) >= 4, "You must have moments at least up to order 4.";
    kappas: list[float] = [0.0] * 4;
    kappas[0] = moments[0];
    kappas[1] = moments[1] - (moments[0] ** 2);
    kappas[2] = (moments[2] - (3 * moments[1] * moments[0])) + (2 * (moments[0] ** 3));
    kappas[3] = (
        (moments[3] - (4 * moments[2] * moments[0]) - (3 * (moments[1] ** 2)))
        + (12 * moments[1] * (moments[0] ** 2))
        - (6 * (moments[0] ** 4))
    );
    return kappas;
}

