"""Return the k-th root of the given integer n, rounded down to the
    nearest integer.
    """
def kth_root_int(n: float, k: float) -> object {
    u = n;
    s = n + 1;
    while (u < s) {
        s = u;
        t = ((k - 1) * s) + (n // pow(s, (k - 1)));
        u = t // k;
    }
    return s;
}

