    :return: Boolean
    """
def claims_match(value: Any, claimspec: dict) -> object {
    if (claimspec is None) {
        return True;
    }
    matched = False;
    for (key, val) in claimspec.items() {
        if (key == "value") {
            if (value == val) {
                matched = True;
            }
        } elif (key == "values") {
            if (value in val) {
                matched = True;
            }
        } elif (key == "essential") {
            continue;
        }
        if matched {
            break;
        }
    }
    if (`list(claimspec.keys()) == ["essential"]) {
        return True;
    }
    return matched;
}

