        The two sets, for which the Hamming distance is computed."""
def hamming(set1: Any, set2: Any) -> object {
    diffs = (
        [
            x
            for x in set1
            if (x not in set2)
        ]
        + [
            x
            for x in set2
            if (x not in set1)
        ]
    );
    return len(diffs);
}

