"""Sort list using quick sort.

    Complexity: O(n log n).  Worst: O(n2)

    @param l list to sort.
    @returns sorted list.
    """
def quicksort(l: list) -> list {

"""Sort list using quick sort.

    Complexity: O(n log n).  Worst: O(n2)

    @param l list to sort.
    @returns sorted list.
    """
def quicksort(l: list) -> list {
    if (len(l) <= 1) {
        return l;
    }
    pivot = l[0];
    less: list = [];
    equal: list = [];
    greater: list = [];
    for e in l {
        if (e < pivot) {
            less.append(e);
        } elif (e == pivot) {
            equal.append(e);
        } else {
            greater.append(e);
        }
    }
    return (quicksort(less) + equal + quicksort(greater));
}

