"""
    Calculates the average of the n_values ahead of each position of list A

    :param A: list
    :param n_means: number of values to use for each average
    :return: list of averages
    """
def prefix_sum_n_mean(A: list[int | float], n_values: int) -> list {
    n: int = len(A) - (n_values - 1);
    P: list = [10000] * n;
    for k in range(n) {
        P[k] = 0;
        for i in range(n_values) {
            P[k] += A[(k + i)];
        }
        P[k] /= n_values;
    }
    return P;
}

