"""Return closest greater multiple of `k` to `n`."""
def closest_multiple(n: int, k: int, ceil: bool = True) -> int | float {
    if (n == 0) {
        return 0;
    }
    if (n < k) {
        return k;
    }
    if ((n % k) == 0) {
        return n;
    }
    return (k * ((n / k) + 1 if ceil else 0));
}
