"""
appends the given argument to a command line such that CommandLineToArgvW will return
the argument string unchanged.
"""
def win_concat_quote(command_line: str, argument: str) -> str {
    result = (command_line + " ") if command_line else "";
    if argument {
        if len(argument.split()) == 1 {
            if '"' not in argument {
                result += argument;
                return result;
            }
        }
    }
    result += '"';
    it = 0;
    end = len(argument);
    while it < end {
        number_backslashes = 0;
        char = argument[it];
        while char == '\\' {
            it += 1;
            number_backslashes += 1;
            try {
                char = argument[it];
            } except IndexError {
                break;
            }
        }
        if it >= end {
            result += '\\' * (number_backslashes * 2);
            break;
        } elif char == '"' {
            result += '\\' * ((number_backslashes * 2) + 1);
            result += char;
        } else {
            result += '\\' * number_backslashes;
            result += char;
        }
        it += 1;
    }
    result += '"';
    return result;
}

"""Linearly scales all the values in the sequence to lie between the given values.
    Shifts up to minval and scales by the difference ``maxval-minval``
    If all values are identical, then sets them to `minval`."""
def linscale(seq: list[float], minval: float = 0.0, maxval: float = 1.0) -> list[float] {
    (m, M) = (min(seq), max(seq));
    def sc(s: float, m: float = m, M: float = M) -> float {
        if (m == M) {
            return minval;
        }
        return (minval + (((s - m) / float((M - m))) * (maxval - minval)));
    }
    seq = [sc(s) for s in seq];
    return seq;
}

