def quick_sort(alist: list) -> list {

"""Implement a sorted in order by value list."""
def quick_sort(alist: list) -> list {
    if (len(alist) < 2) {
        return alist;
    }
    if (len(alist) == 2) {
        if (alist[0] > alist[1]) {
            (alist[0], alist[1]) = (alist[1], alist[0]);
        }
        return alist;
    }
    pivot = alist[0];
    less: list = [];
    greater: list = [];
    for num in alist {
        if (num < pivot) {
            less.append(num);
        }
        if (num > pivot) {
            greater.append(num);
        }
    }
    return (quick_sort(less) + [pivot] + quick_sort(greater));
}

