"""Given an unsorted list with errors and skips, return a nested one.
    [{'level': 1}, {'level': 2}]
    =>
    [{'level': 1, 'children': [{'level': 2, 'children': []}]}]

    A wrong list is also converted:
    [{'level': 2}, {'level': 1}]
    =>
    [{'level': 2, 'children': []}, {'level': 1, 'children': []}]
    """
def nest_toc_tokens(toc_list: list[dict]) -> list[dict] {
    ordered_list: list[dict] = [];
    if len(toc_list) {
        last = toc_list.pop(0);
        last["children"] = [];
        levels: list[int] = [last["level"] as int];
        ordered_list.append(last);
        parents: list[dict] = [];
        while toc_list {
            t = toc_list.pop(0);
            current_level = t["level"] as int;
            t["children"] = [];
            if current_level < levels[-1] {
                levels.pop();
                to_pop = 0;
                for p in reversed(parents) {
                    if current_level <= p["level"] as int {
                        to_pop += 1;
                    } else {
                        break;
                    }
                }
                if to_pop {
                    levels = levels[:-to_pop];
                    parents = parents[:-to_pop];
                }
                levels.append(current_level);
            }
            if current_level == levels[-1] {
                if parents {
                    (parents[-1]["children"] as list).append(t);
                } else {
                    ordered_list.append(t);
                }
            } else {
                (last["children"] as list).append(t);
                parents.append(last);
                levels.append(current_level);
            }
            last = t;
        }
    }
    return ordered_list;
}

