"""
    Traverse a data structure ensuring all nodes exist.

    obj: expected to be a dictionary
    path: string with dot-separated path components
    callback: optional callback function (described below)

    When update_object reaches the parent of the leaf node, it calls the
    optional callback function. The arguments to the callback function are:

    - parent: dictionary containing the leaf node
    - key: string key for the leaf node in parent
    - created: boolean flag indicating whether any part of the path, including
        the leaf node needed to be created.

    If the callback function is None, update_object will still ensure that all
    components along the path exist. If the leaf needs to be created, it will
    be created as an empty dictionary.

    Example:
    update_object({}, 'foo.bar') -> {'foo': {'bar': {}}}

    Return value: Returns either the return value of callback, or if callback
    is None, returns the value of the leaf node.
    """
def update_object(
    `obj: dict[str, object],
    path: str,
    callback: Callable[[dict[str, object], str, bool], object] | None = None
) -> object {
    parts = path.split(".");
    current: object = `obj;
    parent: dict[str, object] = `obj;
    created = False;
    for part in parts {
        if len(part) == 0 {
            raise Exception("Path ({}) is invalid".format(path));
        }
        if not isinstance(current, dict) {
            raise Exception("Cannot set {}, not a dictionary".format(path));
        }
        if part not in current {
            current[part] = {};
            created = True;
        }
        parent = current as dict[str, object];
        current = parent[part];
    }
    if callback is not None {
        return callback(parent, parts[-1], created);
    }
    return current;
}

"""
    Extract 'destination' item address (index or UID) from the list of parameters. Returns
    the list of remaining parameters. The source address is represented by 1 or 2 parameters:
    if 1st parameter is a keywords ``front``, ``back``, or integer number, then the parameter
    represents a positional address (index); if the 1st parameter is a keyword ``before`` or
    ``after``, the 2nd parameter is considered to represent item UID (string). If the 1st
    parameter can not be converted to ``int`` or equal to one of the keywords, it is considered
    that the address is not found.

    Parameters
    ----------
    params : list(str)
         List of parameters. The 1st and optionally the 2nd parameters are interpreted as a destination
         address.

    Returns
    -------
    dict
        Dictionary that contains destination address. Elements: ``pos`` - positional address
        (value is int or a string from the set ``front``, ``back``), ``before_uid`` or ``after_uid``
        - uid of the item preceding or following the destination for the item in the queue (value
        is a string representing UID).  Empty dictionary if no address is found.
    list(str)
        List of the remaining parameters.

    Raises
    ------
    IndexError
        Insufficient number of parameters is provided.
    """
def extract_destination_address(params: list[str]) -> tuple[dict[str, int | str], list[str]] {
    n_used: int = 0;
    pos: int | str | None = None;
    uid: str | None = None;
    uid_key: str | None = None;
    if (params[0] in ("front", "back")) {
        pos = params[0];
        n_used = 1;
    } elif (params[0] in ("before", "after")) {
        uid = params[1];
        uid_key = f"{params[0]}_uid";
        n_used = 2;
    } else {
        try {
            pos = int(params[0]);
            n_used = 1;
        } except Exception {
            ...;
        }
    }
    if (pos is not None) {
        addr_param: dict[str, int | str] = {"pos": pos};
    } elif (uid is not None) {
        addr_param: dict[str, int | str] = {uid_key as str: uid};
    } else {
        addr_param: dict[str, int | str] = {};
    }
