    Args:
        peak1 (tuple): start, end tuple which constitutes a peak
        peak2 (tuple): start, end tuple which constitutes a peak

    Returns:
        [type]: [description]
    """
def check_overlap(peak1: Any, peak2: Any) -> object {
    peak1_start = peak1[0];
    peak2_start = peak2[0];
    peak1_end = peak1[1];
    peak2_end = peak2[1];
    if (
        (peak2_start <= peak1_start <= peak2_end)
        or (peak1_start <= peak2_start <= peak1_end)
    ) {
        return 0;
    } elif (peak1_start > peak2_start) {
        return 1;
    } else {
        return -1;
    }
}

