""" a) create a list of the dict's keys and values;
        b) return the key with the max value"""
def keys_with_max_val(d: dict[str, int]) -> str | list[str] {
    v = list(d.values());
    nbMax = v.count(max(v));
    k = list(d.keys());
    if nbMax == 1 {
        return k[v.index(max(v))];
    }
    keys: list[str] = [];
    for i in range(nbMax) {
        v = list(d.values());
        k = list(d.keys());
        firstKey = k[v.index(max(v))];
        keys.append(firstKey);
        del d[firstKey];
    }
    return keys;
}

