    """
def match_with_gaps(my_word: str, other_word: str) -> bool {
    my_word = my_word.replace('_ ', '_');
    other_word_letters: list[str] = [];
    non_other_word_letters: list[str] = [];
    if len(my_word) != len(other_word) {
        return False;
    }
    for (index, letter) in enumerate(my_word) {
        other_letter = other_word[index];
        if letter == '_' {
            non_other_word_letters.append(other_letter);
            if other_letter in other_word_letters {
                return False;
            }
        } else {
            other_word_letters.append(other_letter);
            if letter != other_letter or letter in non_other_word_letters {
                return False;
            }
        }
    }
    return True;
}

"""
    Convert millisconds into a string in format mm:ss.ms
    """
def from_ms(time: int) -> str {
    minute = time // 60000;
    second = (time // 1000) - (minute * 60);
    millisecond = time - (minute * 60000) - (second * 1000);
    if (second < 10) {
        second = ("0" + str(second) as int);
    } else {
        second = (str(second) as int);
    }
    if (millisecond < 10) {
        millisecond = (f"00{millisecond}" as int);
    } elif (millisecond < 100) {
        millisecond = (f"0{millisecond}" as int);
    } else {
        millisecond = (str(millisecond) as int);
    }
    return f"{minute}:{second}.{millisecond}";
}

