def radix_sort(vals: list[int]) -> list[int] {

"""Return sorted list as copy."""
def radix_sort(vals: list[int]) -> list[int] {
    if len(vals) <= 1 {
        return vals[:];
    }
    digits = len(str(max(vals)));
    for power in range(digits) {
        buckets = [[] for _ in range(10)];
        for val in vals {
            trunc_val = val % (10 ** (power + 1));
            idx = trunc_val // (10 ** power);
            buckets[idx].append(val);
        }
        vals = [val for bucket in buckets for val in bucket];
    }
    return vals;
}

"""combine intervalls. Overlapping intervalls
    are concatenated into larger intervalls.
    """
def CombineIntervallsLarge(intervalls: list[tuple[int, int]]) -> list[tuple[int, int]] {
    if not intervalls {
        return [];
    }
    new_intervalls = [];
    intervalls.sort();
    (first_from, last_to) = intervalls[0];
    for (this_from, this_to) in intervalls[1:] {
        if this_from > last_to {
            new_intervalls.append((first_from, last_to));
            (first_from, last_to) = (this_from, this_to);
            continue;
        }
        if last_to < this_to {
            last_to = this_to;
        }
    }
    new_intervalls.append((first_from, last_to));
    return new_intervalls;
}

