def topo_sorted(depmap: dict[object, list[object]]) -> list[object] {
    ordered: list[object] = [
        item
        for (item, requires) in depmap.items()
        if not requires
    ];
    remaining: dict[object, set[object]] = {
        item: set(requires)
        for (item, requires) in depmap.items()
        if requires
    };
    satisfied: set[object] = set(ordered);
    while remaining {
        additions: list[object] = [];
        for (item, requires) in list(remaining.items()) {
            if requires.issubset(satisfied) {
                additions.append(item);
                satisfied.add(item);
                del remaining[item];
            }
        }
        if not additions {
            raise ValueError(("unsatisfiable", remaining));
        }
        ordered.extend(additions);
        additions = [];
    }
    return ordered;
}

