"""
    Convert part-of-speech tags (Penn Treebank tagset) to the 4 tags {_N, _V, _J, _X} for
    nounds, verbs, adjectives/adverbs, and others.
    Beware that this method takes a list of tuples and returns a list of strings.
    :param tagged_words: [(str,str)] -- words and their associated POS-tags
    :return: [str] -- words ending with {_N, _V, _J, _X}
    """
def simplify_postags(tagged_words: Any) -> object {
    postags = {
        "N": ["NN", "NNS", "NNP", "NNPS"],
        "V": ["VB", "VBD", "VBG", "VBN", "VBZ", "VBP"],
        "J": ["JJ", "JJR", "JJS"]
    };
    simplified = [];
    for (w, t) in tagged_words {
        if (t in postags["N"]) {
            simplified.append("_".join([w, "N"]));
        } elif (t in postags["V"]) {
            simplified.append("_".join([w, "V"]));
        } elif (t in postags["J"]) {
            simplified.append("_".join([w, "J"]));
        } else {
            simplified.append("_".join([w, "X"]));
        }
    }
    return simplified;
}

"""string = Int2AP(num)
    Return 'num' converted to bytes using characters from the set 'A'..'P'
    """
def Int2AP(num: int | float) -> object {
    val: bytes = b'';
    AP: bytes = b'ABCDEFGHIJKLMNOP';
    num: int = int(abs(num));
    while num {
        (num, mod) = divmod(num, 16);
        val = AP[mod:(mod + 1)] + val;
    }
    return val;
}

"""
    Grading Scale -
        89.50 - 100     = A \n
        88.50 - 89.49   = B+ \n
        79.50 - 88.49   = B \n
        78.50 - 79.49   = C+ \n
        69.50 - 78.49   = C \n
        68.50 - 69.49   = D+ \n
        59.50 - 68.49   = D \n
        00.00 - 59.50   = F \n

    @type grade: float
    @param grade: float
    @return: str
    """
def find_letter_grade(grade: float) -> str {
    if (`type(grade) != float) {
        if (`type(grade) == int) {
            grade_to_convert = float(grade);
        } else {
            raise TypeError(
                (
                    "Input was: "
                    + str(`type(grade))
                    + " --> input must be either <class 'float'> OR <class 'int'>!"
                )
            );
        }
    } else {
        grade_to_convert = grade;
    }
    if (grade_to_convert >= 89.5) {
        return "A";
    } elif (grade_to_convert >= 88.5 < 89.5) {
        return "B+";
    } elif (grade_to_convert >= 79.5 < 88.5) {
        return "B";
    } elif (grade_to_convert >= 78.5 < 79.5) {
        return "C+";
    } elif (grade_to_convert >= 69.5 < 78.5) {
        return "C";
    } elif (grade_to_convert >= 68.5 < 69.5) {
        return "D+";
    } elif (grade_to_convert >= 59.5 < 68.5) {
        return "D";
    } else {
        return "F";
    }
}

