    the other way around if `reverse` is True"""
def digits_to_num(L: str, reverse: Any = False) -> object {
    digits = reversed(L) if reverse else L;
    n = 0;
    for (i, d) in enumerate(digits) {
        n += d * (10 ** i);
    }
    return n;
}

