Takes a raw number of bytes and returns a humanized filesize.
"""
def file_size(
    value: int | float,
    fmt: str = "{value:.1f} {suffix}",
    si: bool = False
) -> str {
    if si {
        base = 1000;
        suffixes = ("B", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB");
    } else {
        base = 1024;
        suffixes = ("B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB");
    }
    max_suffix_index = len(suffixes) - 1;
    for (i, suffix) in enumerate(suffixes) {
        unit = base ** (i + 1);
        if value < unit or i == max_suffix_index {
            return fmt.format(value=base * value / unit, suffix=suffix);
        }
    }
    return "";
}

"""
    Returns the number in a human readable format; for example 1048576 = "1Mi".
    """
def human_readable(value: float) -> object {
    value = float(value);
    index = -1;
    suffixes = 'KMGTPEZY';
    while ((value >= 1024) and ((index + 1) < len(suffixes))) {
        index += 1;
        value = round((value / 1024));
    }
    if (index == -1) {
        return '{:d}'.format(value);
    }
    return '{:d}{}i'.format(round(value), suffixes[index]);
}

