"""
    Find left limit.
    Args:
       minpoint (int): x coordinate of the local minimum
       ds (list): list of numbers representing derivative of the time-series signal s
       tau (int): threshold to determine a slope 'too sharp'
    Returns:
       minpoint (int): x coordinate of the left-modified local minimum
    """
def leftlimit(minpoint: int, ds: list[float], tau: int) -> int {
    slope = ds[minpoint - 1];
    while (slope > tau and slope < 0 and minpoint > 0) {
        minpoint -= 1;
        slope = ds[minpoint - 1];
    }
    return minpoint;
}

"""
    Convert a nested dictionary from one convention to another.
    Args:
        dic (dict): dictionary (nested or not) to be converted.
        convert (func): function that takes the string in one convention and
                        returns it in the other one.
    Returns:
        Dictionary with the new keys.
    """
def naming_convention(dic: dict, convert: Any) -> object {
    new = {};
    for (key, value) in dic.items() {
        converted_value = value;
        if isinstance(value, `dict) {
            converted_value = naming_convention(value, convert);
        } elif isinstance(value, `list) {
            converted_value = [];
            for each_value in value {
                if isinstance(each_value, `dict) {
                    converted_value.append(naming_convention(each_value, convert));
                } else {
                    converted_value.append(each_value);
                }
            }
        }
        new[convert(key)] = converted_value;
    }
    return new;
}

