    :param in_str:
    :param kwargs: the arguments to substitute
    :return:
    >>> fancy_format('{haha} {dan} {bob}', dan = 1, bob = 2)
    '{haha} 1 2'
    """
def fancy_format(in_str: str, **kwargs: int | str | float | bool) -> str {
    new_str: str = in_str.replace('{', '{{').replace('}', '}}');
