       return the number of bytes.  Will return 0 if the argument has
       unexpected form.
    """
def human_to_bytes(size: Any) -> object {
    `bytes = size[:-1];
    unit = size[-1].upper();
    if `bytes.isdigit() {
        `bytes = int(`bytes);
        if (unit == 'P') {
            `bytes *= 1125899906842624;
        } elif (unit == 'T') {
            `bytes *= 1099511627776;
        } elif (unit == 'G') {
            `bytes *= 1073741824;
        } elif (unit == 'M') {
            `bytes *= 1048576;
        } elif (unit == 'K') {
            `bytes *= 1024;
        } else {
            `bytes = 0;
        }
    } else {
        `bytes = 0;
    }
    return `bytes;
}

