                {'both': {'own_log'}, 'stdout': {'own_log'}, 'stderr': {'own_log'}}
            );
        } elif (config == 'full') {
            normalized_config.update(
                {
                    'both': {'screen', 'log', 'own_log'},
                    'stdout': {'own_log'},
                    'stderr': {'own_log'}
                }
            );
        } else {
            raise ValueError(
                '{} is not a valid standard output config '
                'i.e. "screen", "log" or "both"'.format(
                    config
                )
