"""The bits whose parity stores the occupation of mode `index`."""
def _occupation_set(index: int) -> object {
    indices = set();
    index += 1;
    indices.add((index - 1));
    parent = index & (index - 1);
    index -= 1;
    while (index != parent) {
        indices.add((index - 1));
        index &= index - 1;
    }
    return indices;
}

