    dbox is (x1, x2, y1, y2),
    v is (lat, long).
    result is (x, y)
    """
def map_box(sbox: list, dbox: list, v: list) -> object {
    xscale = abs((dbox[1] - dbox[0])) / abs((sbox[3] - sbox[2]));
    yscale = abs((dbox[3] - dbox[2])) / abs((sbox[1] - sbox[0]));
