"""
	Find x = dlog_g(t) in Z/pZ*, given that is in [b, b+w].
	"""
def pollardlambda(
    g: int, p: int, t: int, q: int, b: int, w: int, theta: int = 8
) -> int {
    import from itertools { count }
    import from math { sqrt }
    L = 5;
    def f(TW: int) -> int {
        return pow(2, (TW % L));
    }
    a = 1 / (2 * sqrt(theta));
    m = a * sqrt(w);
    N = int((m * theta));
    MAX_WILD_ITERS = 10 ** 5;
    T = pow(g, (b + w), p);
    W = t;
    if (W == T) {
        return ((b + w) % q);
    }
    dT = 0;
    for i in range(N) {
        dT += f(T);
        T = (T * pow(g, f(T), p)) % p;
    }
    dW = 0;
    for j in count() {
        dW += f(W);
        W = (W * pow(g, f(W), p)) % p;
        if (W == T) {
            return (((b + w + dT) - dW) % q);
        }
        if (dW > (w + dT)) {
            raise RuntimeError(('Failure: ' + str((g, p, t, q, b, w))));
        }
    }
    raise RuntimeError(('Discrete log not found: ' + str((g, p, t, q, b, w))));
}

