"""PFA division behavior: inf and -inf for a finite number divided by zero and nan for 0/0.

    Also ensures that return type of any two numbers (including integers) is floating point.

    :type numer: number
    :param numer: the numerator
    :type denom: number
    :param denom: the denominator
    :rtype: float
    :return: fraction, including non-numeric possibilities
    """
def div(numer: float, denom: float) -> object {
    try {
        return (numer / float(denom));
    } except ZeroDivisionError {
        if (numer > 0.0) {
            return float("inf");
        } elif (numer < 0.0) {
            return float("-inf");
        } else {
            return float("nan");
        }
    }
}

"""
    Bellman ford shortest path algorithm

    Parameters
    ----------
    nodes : set
            names of all nodes in the graph
    edges : list
            list of dependencies between nodes in the graph
            [(node1, node2, weight), ...]
    source : str
            name of source node

    Returns
    -------
    out : (bool, dict)
          (has_cycle, distances) has_cycle var check if cycle in the graph
          distance dict show len from source node to all nodes in the graph

    """
def bellman_ford(
    nodes: set[str],
    edges: list[tuple[str, str, int]],
    source: str
) -> tuple[bool, dict[str, float]] {
    distances = {`node: float('Inf') for `node in nodes};
    distances[source] = 0;
    for _ in range(1, len(nodes)) {
        for (src, dest, weight) in edges {
            if distances[dest] > distances[src] + weight {
                distances[dest] = distances[src] + weight;
            }
        }
    }
    has_cycle = False;
    for (src, dest, weight) in edges {
        if distances[dest] > distances[src] + weight {
            has_cycle = True;
        }
    }
    return (has_cycle, distances);
}

