    pivots = [];
    radius = diameter / 2;
    sqval = (radius ** 2) - (y ** 2);
    if (sqval > 0) {
        sqrt = sqval ** 0.5;
        pivots.append(((x + sqrt), 0));
        pivots.append(((x - sqrt), 0));
    } elif (sqval == 0) {
        pivots.append((x, 0));
    }
    sqval = (radius ** 2) - (x ** 2);
    if (sqval > 0) {
