"""Return a list of prime factors for a given number in ascending order if
    the number of prime factors equals k."""
def prime_factors(n: int, primes: list[int], factors: list[int] | None = None) -> list[int] {
    factors = [];
    for p in primes {
        while n >= (p * p) {
            if n % p {
                break;
            } else {
                n = n // p;
                factors.append(p);
            }
        }
    }
    factors.append(n);
    return factors;
}

