"""
I2OSP aka RSA's standard ascii decoder. Decodes integer X into
multiple bytes and converts those ASCII codepoints into an ASCII string.
"""
def rsa_ascii_decode(x: int, x_len: int) -> str {
    bytes_out = [];
    if x >= pow(256, x_len) {
        raise ValueError('Number is too large to fit in output string.');
    }
    while x > 0 {
        bytes_out.append(x % 256);
        x //= 256;
    }
    for _ in range(x_len - len(bytes_out)) {
        bytes_out.append(0);
    }
    return ''.join([chr(b) for b in bytes_out[::-1]]);
}

"""Rename variable names in ``fitarg`` with rename function.

    ::

        #simple renaming
        fitarg_rename({'x':1, 'limit_x':1, 'fix_x':1, 'error_x':1},
            lambda pname: 'y' if pname=='x' else pname)
        #{'y':1, 'limit_y':1, 'fix_y':1, 'error_y':1},

        #prefixing
        figarg_rename({'x':1, 'limit_x':1, 'fix_x':1, 'error_x':1},
            lambda pname: 'prefix_'+pname)
        #{'prefix_x':1, 'limit_prefix_x':1, 'fix_prefix_x':1, 'error_prefix_x':1}

    """
def fitarg_rename(fitarg: dict, ren: str | any) -> object {
    if isinstance(ren, str) {
        s: str = ren;
        ren = lambda (x: str) { (s + "_" + x); };
    }
    ret: dict = {};
    prefix: list[str] = ["limit_", "fix_", "error_"];
    for (k, v) in fitarg.items() {
        vn: str = k as str;
        pf: str = "";
        for p in prefix {
            if (k as str).startswith(p) {
                i = len(p);
                vn = (k as str)[i:];
                pf = p;
            }
        }
        newvn: str = pf + (ren(vn) as str);
        ret[newvn] = v;
    }
    return ret;
}

