"""Input float, Returns formatted dollars($x,xxx.xx)"""
def format_dollars(amount: int | float) -> str {
    balance = '{:.2f}'.format(amount);
    parts = balance.split('.');
    reversed_digits = parts[0][::-1];
    new_thing = '';
    for i in range(1, len(reversed_digits) + 1) {
        if (i - 1) % 3 == 0 and i != 1 {
            new_thing += ',';
        }
        new_thing += reversed_digits[i - 1];
    }
    '$' + new_thing[::-1] + '.' + parts[1]
}

"""
       Converts 'something' to boolean. Raises exception for invalid formats
           Possible True  values: 1, True, "1", "TRue", "yes", "y", "t"
           Possible False values: 0, False, None, [], {}, "", "0", "faLse", "no", "n", "f", 0.0, ...
    """
def to_bool_str(value: Any) -> object {
    if (str(value).lower() in ("yes", "y", "true", "t", "1")) {
        return "1";
    }
    if (
        str(value).lower()
        in ("no", "n", "false", "f", "0", "0.0", "", "none", "[]", "{}")
    ) {
        return "0";
    }
    raise Exception(('Invalid value for boolean conversion: ' + str(value)));
}

"""
    Invert the key:values of a dict
    :param dict_in: dict to invert
    :param append_list: append to a list? (for non-uniqueness)
    :return: inverted dict
    """
def invert_dict[K, V](dict_in: dict[K, V], append_list: bool = False) -> dict[V, K] | dict[V, list[K]] {
    if not append_list {
        return {val: key for (key, val) in dict_in.items()};
    }
    dict_out: dict[V, list[K]] = {val: [] for (key, val) in dict_in.items()};
    for (key, val) in dict_in.items() {
        dict_out[val].append(key);
    }
    return dict_out;
}

"""Modify license for file type

    Args:
        license (str): License to be inserted
        settings (Dict): File type settings

    Returns:
        str: Modified license to be inserted in the file
    """
def get_license(license: str, settings: dict) -> object {
    lines = [];
    header_start_line = settings["headerStartLine"];
    header_end_line = settings["headerEndLine"];
    header_line_prefix = settings["headerLinePrefix"];
    header_line_suffix = settings["headerLineSuffix"];
    if (header_start_line is not None) {
        lines.append(header_start_line.rstrip());
    }
    for line in license.split("\n") {
        tmp = line;
        if (header_line_prefix is not None) {
            tmp = header_line_prefix + tmp;
        }
        if (header_line_suffix is not None) {
            tmp = tmp + header_line_suffix;
        }
        lines.append(tmp.rstrip());
    }
    if (header_end_line is not None) {
        lines.append(header_end_line.rstrip());
    }
    return ("\n".join(lines) + "\n");
}

