        if (group[0] and group[1]) {
            dn = 'DistinguishedName';
            if ((dn in group_object) and group_object[dn]) {
                group.insert(0, group_object[dn]);
            } else {
                group.insert(0, '');
            }
            groups.append(group);
        }
    }
    return groups;
}

