def pythagorean_triples(n: int) -> object {
    res = [];
    for i in range(1, (n + 1)) {
        for j in range(1, (n + 1)) {
            for k in range(1, (n + 1)) {
                if ((i <= j <= k) and (((i ** 2) + (j ** 2)) == (k ** 2))) {
