"""Extended Euclid's algorithm for the modular inverse calculation.
    """
def egcd(a: int, b: int) -> tuple[int, int, int] {
    if (a == 0) {
        return (b, 0, 1);
    }
    (g, y, x) = egcd((b % a), a);
    return (g, (x - ((b // a) * y)), y);
}
