"""Convert an RGB color to HSV."""
def rgb2hsv(c: tuple[int | float, int | float, int | float]) -> tuple[float, float, float] {

"""Convert an RGB color to HSV."""
def rgb2hsv(c: tuple[int | float, int | float, int | float]) -> tuple[float, float, float] {
    (r, g, b) = c;
    v = max(r, g, b);
    mn = min(r, g, b);
    delta = v - mn;
    h: float = 0.0;
    if (v == mn) {
        h = 0.0;
    } elif (v == r) {
        h = ((60 * (g - b)) / delta) + (0 if (g >= b) else 360);
    } elif (v == g) {
        h = ((60 * (b - r)) / delta) + 120;
    } else {
        h = ((60 * (r - g)) / delta) + 240;
    }
    s = 0 if (v == 0) else (1 - (mn / v));
    return (h, s, v);
}

"""Rearrange list_[i:j] so that items < list_[i] are at
    the beginning and items >= list_[i] are at the end,
    and return the new index for list_[i].
    """
def _partition_2(list_: list[int], i: int, j: int) -> int {
    v = list_[i];
    k = i + 1;
    j -= 1;
    while k <= j {
        if list_[k] < v {
            k += 1;
        } else {
            (list_[k], list_[j]) = (list_[j], list_[k]);
            j -= 1;
        }
    }
    (list_[i], list_[j]) = (list_[j], list_[i]);
    return j;
}

