) -> object {
    if ignore_missing {
        signatures = {
            tissue: [
                gene
                for gene in genes
                if (gene in rosetta)
            ] for (tissue, genes) in signatures.items()
        };
    }
    return {
        tissue: [rosetta[gene] for gene in genes]
        for (tissue, genes) in signatures.items()
    };
}

