def get_dynamic_hasher_names(HMAC_KEYS: dict) -> object {
    algo_name = lambda (hmac_id: Any) { 'bcrypt{0}'.format(
        (hmac_id as str).replace('-', '_')
    ); };
    return [algo_name(key) for key in sorted(HMAC_KEYS.keys(), reverse=True)];
}

