"""GCD(x:long, y:long): long
    Return the GCD of x and y.
    """
def GCD(x: int, y: int) -> int {
    x = abs(x);
    y = abs(y);
    while x > 0 {
        (x, y) = (y % x, x);
    }
    return y;
}

"""
    Split string

    Parameters
    ----------
    str : str
        string to split

    limit : int
        string length limit

    sep : str
        separator
        default: "\n"

    Returns
    -------
    True if blockquotes are balanced, False otherwise
    """
def split_string(str: str, limit: int, sep: str = "\n") -> object {
    limit = int(limit);
    words: list[str] = str.split(sep);
    if (max(map(len, words)) > limit) {
        return str;
    }
    (res, part, others) = ([] as list[str], words[0], words[1:]);
    for word in others {
        if ((len(sep) + len(word)) > (limit - len(part))) {
            res.append(part);
            part = word;
        } else {
            part += sep + word;
        }
    }
    if part {
