"""
    Check if a list (_list) starts with all the items from another list (lstart)
    :param _list: list
    :param lstart: list
    :return: bool, True if _list starts with all the items of lstart.
    """
def list_startswith(_list: list[str] | None, lstart: list[str]) -> bool {
    if _list is None {
        return False;
    }
    lenlist = len(_list);
    lenstart = len(lstart);
    if lenlist >= lenstart {
        return _list[:lenstart] == lstart;
    }
    return False;
}

