"""http://en.wikipedia.org/wiki/Luhn_algorithm ."""
def luhn_checksum(check_number: int | str) -> int {
    def digits_of(n: int | str) -> list[int] {
        return [int(d) for d in str(n)];
    }
    digits = digits_of(check_number);
    odd_digits = digits[-1::-2];
    even_digits = digits[-2::-2];
    checksum = 0;
    checksum += sum(odd_digits);
    for d in even_digits {
        checksum += sum(digits_of(d * 2));
    }
    return checksum % 10;
}
```

"""Parse a config's "1,2,3"-style string into a list of ints.

  Args:
    s: The string to be parsed, or possibly already an int.
    repeats_if_single: If s is already an int or is a single element list,
                       repeat it this many times to create the list.

  Returns:
    A list of integers based on `s`.
  """
def str2intlist(s: int | str, repeats_if_single: int | None = None) -> list[int | None] {
    if isinstance(s, int) {
        result: list[int | None] = [s];
    } else {
        result: list[int | None] = [int(i.strip()) if (i != "None") else None for i in s.split(",")];
    }
    if ((repeats_if_single is not None) and (len(result) == 1)) {
        result *= repeats_if_single;
    }
    return result;
}

"""Find the cluster class for each vertex of the MST graph.
    It uses the DFS-like algorithm to find clusters.

    Args:
        mst_graph (dict): A non-empty graph representing the MST.
        vertices (list): A list of unique vertices.

    Returns:
        A list containing the group id of each vertex.
    """
def _find_clusters(mst_graph: Any, vertices: Any) -> object {
    cluster_id = 0;
    classes = [-1] * len(vertices);
    unexplored = vertices.copy();
    while unexplored {
        start = unexplored.pop();
        classes[start] = cluster_id;
        (explored, stack) = (`set(), [start]);
        while stack {
            v = stack.pop();
            if (v in explored) {
                continue;
            }
            if (v != start) {
                unexplored.remove(v);
            }
            explored.add(v);
            classes[v] = cluster_id;
            if (v not in mst_graph) {
                continue;
            }
            for adj in mst_graph[v] {
                if (adj in explored) {
                    continue;
                }
                stack.append(adj);
            }
        }
        cluster_id += 1;
    }
    return (classes, cluster_id);
}

