            Parameters:
            json_dict (dict): Holds the json data
            delim (string): The delimiter to be used to create flattened keys

            Returns:
            flattened_dict (dict): Holds the flattened dictionary
    """
def flatten_json(
    json_dict: dict[str, str | int | float | bool | list | dict],
    delim: str
) -> dict[str, str | int | float | bool | list] {
    flattened_dict: dict[str, str | int | float | bool | list] = {};
    for i in json_dict.keys() {
        if isinstance(json_dict[i], dict) {
            get = flatten_json(
                json_dict[i] as dict[str, str | int | float | bool | list | dict],
                delim
            );
            for j in get.keys() {
                flattened_dict[i + delim + j] = get[j];
            }
        } else {
            flattened_dict[i] = json_dict[i] as str | int | float | bool | list;
        }
    }
    return flattened_dict;
}

