"""
    Calculate the area of a *simple* polygon
    """
def shoelace_area(points: list) -> object {
    n = len(points);
    area = 0.0;
    for i in range(n) {
        j = (i + 1) % n;
        area += points[i][0] * points[j][1];
        area -= points[j][0] * points[i][1];
    }
    area = abs(area) / 2.0;
    return area;
}

