"""Given a value, attempt to coerce it to either an integer or float."""
def _to_mumps_number(v: Any) -> object {
    sign = 1;
    ndec = 0;
    try {
        tmp = float(v);
        if tmp.is_integer() {
            return int(tmp);
        } else {
            return tmp;
        }
    } except ValueError {
        v = str(v);
        n = [];
        for c in v {
            if (c.isnumeric() or (c in ('.', '+', '-'))) {
                if (c == '.') {
                    if (ndec >= 1) {
                        break;
                    } else {
                        ndec += 1;
                    }
                }
                if (c == '-') {
                    sign *= -1;
                    continue;
                }
                if (c == '+') {
                    continue;
                }
                n.append(c);
            } else {
                break;
            }
        }
        n = float("".join(n)) * sign;
        return n if not n.is_integer() else int(n);
    }
}
