        return 'SandyBridge';
    }
    if (`node.strip() in [('c' + str(x)) for x in range(321, 479)]) {
        return 'SandyBridge';
    }
    if (`node.strip() in [('c' + str(x)) for x in range(579, 629)]) {
        return 'Haswell';
