    This module limits the values to the range of [0,limit]
    """
def limit_x(x: float, limit: float) -> float {
    x_gr_limit = x > limit;
    x_le_limit = (x_gr_limit * limit) + ((1 - x_gr_limit) * x);
    x_gr_zero = x > 0.0;
    x_norm = x_gr_zero * x_le_limit;
    return x_norm;
}

