"""
    Inkscape default: 90dpi == 1-to-1 for 100px.
    """
def icon_dpi(px: int, icon: dict) -> object {
    (x1, y1, x2, y2) = [float(a) for a in icon['view_box'].split(" ")];
    width = x2 - x1;
    height = y2 - y1;
    if (width < 0) {
        width = 100;
    }
    if (height < 0) {
        height = 100;
    }
    return ((90.0 / max(width, height)) * px);
}

