"""
    Converts seconds to a short user friendly string
    Example: 143 -> 2m 23s
    """
def durationToText(seconds: int | float) -> str {
    days: int = int((seconds / 86400000));
    if days {
        return '{0} day{1}'.format(days, (((days > 1) and 's') or ''));
    }
    left: int | float = seconds % 86400000;
    hours_count: int = int((left / 3600000));
    hours: str = '';
    if hours_count {
        hours = '{0} hr{1} '.format(hours_count, (((hours_count > 1) and 's') or ''));
    }
    left = left % 3600000;
    mins: int = int((left / 60000));
    if mins {
        return (hours + '{0} min{1}'.format(mins, (((mins > 1) and 's') or '')));
    } elif hours {
        return hours.rstrip();
    }
    secs: int | float = int((left % 60000));
    if secs {
        secs /= 1000;
        return '{0} sec{1}'.format(secs, (((secs > 1) and 's') or ''));
    }
    return '0 seconds';
}

