def argmax(seq: Sequence[str], fn: Callable[[str], int]) -> str | int {
    if (len(seq) == 1) {
        return seq[0];
    }
    best: str | int = -1;
    best_score: float = float("-inf");
    for x in seq {
        x_score = fn(x);
        if (x_score > best_score) {
            (best, best_score) = (x, x_score);
        } elif (x_score == best_score) {
            (best, best_score) = (2, x_score);
        }
    }
    return best;
}
