"""Return True if key is not a boring standard FITS keyword.

    To make the data model more human readable, we don't overwhelm the output
    with required keywords which are required by the FITS standard anyway, or
    cases where the number of headers might change over time.

    This list isn't exhaustive.

    Parameters
    ----------
    key : :class:`str`
        A FITS keyword.

    Returns
    -------
    :class:`bool`
        ``True`` if the keyword is not boring.

    Examples
    --------
    >>> extrakey('SIMPLE')
    False
    >>> extrakey('DEPNAM01')
    False
    >>> extrakey('BZERO')
    True
    """
def extrakey(key: Any) -> object {
    import from re { match }
    if (
        key
        in (
            'BITPIX',
            'NAXIS',
            'PCOUNT',
            'GCOUNT',
            'TFIELDS',
            'XTENSION',
            'SIMPLE',
            'EXTEND',
            'COMMENT',
            'HISTORY',
            'EXTNAME',
            ''
        )
    ) {
        return False;
    }
    if (`match(r'T(TYPE|FORM|UNIT|COMM|DIM)\d+', key) is not None) {
        return False;
    }
    if (
        `match(
            r'Z(IMAGE|TENSION|BITPIX|NAXIS|NAXIS1|NAXIS2|PCOUNT|GCOUNT|TILE1|TILE2|CMPTYPE|NAME1|VAL1|NAME2|VAL2|HECKSUM|DATASUM)',
            key
        )
        is not None
    ) {
        return False;
    }
    if (`match(r'DEP(NAM|VER)\d+', key) is not None) {
        return False;
    }
    return True;
}

