"""Internal Numba implementation of the Lempel-Ziv (LZ) complexity."""
def _lz_complexity(binary_string: list[int]) -> int {

"""Internal Numba implementation of the Lempel-Ziv (LZ) complexity."""
def _lz_complexity(binary_string: list[int]) -> int {
    complexity = 1;
    prefix_len = 1;
    len_substring = 1;
    max_len_substring = 1;
    pointer = 0;
    while prefix_len + len_substring <= len(binary_string) {
        if binary_string[pointer + len_substring - 1] == binary_string[prefix_len + len_substring - 1] {
            len_substring += 1;
        } else {
            max_len_substring = max(len_substring, max_len_substring);
            pointer += 1;
            if pointer == prefix_len {
                complexity += 1;
                prefix_len += max_len_substring;
                pointer = 0;
                max_len_substring = 1;
            }
            len_substring = 1;
        }
    }
    if len_substring != 1 {
        complexity += 1;
    }
    return complexity;
}

"""# problem due to inverted Tkinker canvas, so i do opposite of
    below:

    Checks to see if points are in counterclockwise order which denotes a
    inner ring of a polygon that has a donut-like shape or a hole such as
    a lake etc.

    Argument:
    ring - a list of tuples denoting x,y coordinates [(x1,y1),...]

    Return:
    TRUE or FALSE

    Notes:
    http://www.cartotalk.com/index.php?showtopic=2467
    Charlie Frye 9/26/07 says:
    "Ring order could mean one of two things. First, when a shape has more than one
    part, e.g., a donut hole or an island, it's shape will be comprised of
    multiple parts, or rings. Each ring defines the geometry (list of
    coordinates). The expected implementation is that the rings are listed in size
    order, with the largest ring (covering the most area) being first in the list.
    Another issue is whether the coordinates in each ring are listed in clockwise
    or counterclockwise order; clockwise means it is an exterior ring or an
    island, and counterclockwise is an interior ring or an island [ A HOLE ]."
    """
def isHole(ring: Any) -> object {
    x = [p[0] for p in ring];
    y = [p[1] for p in ring];
    n = len(x);
    a = sum([((x[i] * y[(i + 1)]) - (x[(i + 1)] * y[i])) for i in range((n - 1))]);
    if (a > 0) {
        counterClockWise = True;
        hole = False;
    } else {
        counterClockWise = False;
        hole = True;
    }
    return hole;
}

"""
    Removes key:value pairs from a dict
        If a direct trim, the provided attributes will be removed from the dict
        If an indirect trim, the provided attributes will be kept, and all other
        attributes will be deleted
    """
type DictVal = str | int | float | bool | None | list[DictVal] | dict[str, DictVal];

def trimDict(dict: dict[str, DictVal], direct: bool = True, *attrs: str) -> dict[str, DictVal] {
    if direct {
        for attr in attrs {
            if (attr in dict) {
                dict.pop(attr);
            }
        }
    } else {
        for key in dict {
            if (key not in attrs) {
                dict.pop(key);
            }
        }
    }
    return dict;
}

