"""
    Returns a number within the range [0, 1] determining how similar
    item1 is to item2. 0 indicates perfect dissimilarity while 1
    indicates equality. The similarity value is calculated by counting
    the number of bigrams both words share in common.
    """
def bigram_similarity(word1: str, word2: str) -> float {
    word1 = word1.lower();
    word2 = word2.lower();
    word1_length = len(word1);
    word2_length = len(word2);
    pairs1 = [];
    pairs2 = [];
    for i in range(word1_length) {
        if (i == (word1_length - 1)) {
            continue;
        }
        pairs1.append((word1[i] + word1[(i + 1)]));
    }
    for i in range(word2_length) {
        if (i == (word2_length - 1)) {
            continue;
        }
        pairs2.append((word2[i] + word2[(i + 1)]));
    }
    similar = [
        word
        for word in pairs1
        if (word in pairs2)
    ];
    return (float(len(similar)) / float(max(len(pairs1), len(pairs2))));
}

"""Searches string S and finds the first substring found between the
	BEFORE and AFTER substrings, if they are found.

	Returns the indexes of the start and end of the found substring,
	such that s[start:end] would be the substring. (first character, last character + 1)

	If not found, (0,0) is returned.

	example:
	>>> find_between("hayneedlestack", "hay", "stack")
	(3, 9)

	>>> find_between("hello world", "hay", "stack")
	(0, 0)
	"""
def find_between(s: str, before: str, after: str) -> object {
    start = s.find(before) + len(before);
    if (start < 0) {
        return (0, 0);
    }
    end = s[start:].find(after);
    if (end < 0) {
        return (0, 0);
    }
    return (start, (start + end));
}

