    Calculate relative object ratios in the labeled image.
    Args:
        x1: Start x coordinate.
        y1: Start y coordinate.
        x2: End x coordinate.
        y2: End y coordinate.
        width: Bounding box width.
        height: Bounding box height.

    Return:
        bx: Relative center x coordinate.
        by: Relative center y coordinate.
        bw: Relative box width.
        bh: Relative box height.
    """
def calculate_ratios(
    x1: float, y1: float, x2: float, y2: float, width: float, height: float
) -> tuple[float, float, float, float] {
    box_width = abs((x2 - x1));
    box_height = abs((y2 - y1));
    bx = 1 - (((width - min(x1, x2)) + (box_width / 2)) / width);
    `by = 1 - (((height - min(y1, y2)) + (box_height / 2)) / height);
    bw = box_width / width;
    bh = box_height / height;
    return (bx, `by, bw, bh);
}

"""
        Takes an integer argument limit, and returns the largest square number
        that is less than limit. A square number is the product of an
        integer multiplied by itself, for example 36 is a square number because
        it equals 6*6.
        """
def nearest_square(y: Any) -> object {
    x = 0;
    while ((x ** 2) <= y) {
        x += 1;
    }
    if (x >= 1) {
        return ((x - 1) ** 2);
    } else {
        return 0;
    }
}

