"""Returns True if n is prime.

    It uses the fact that a prime (except 2 and 3) is of form 6k - 1 or 6k + 1.
    Function looks only at divisors of this form (after checking 2 & 3).
    """
def isprime(n: float) -> object {
    if (n == 2) {
        return True;
    }
    if (n == 3) {
        return True;
    }
    if ((n % 2) == 0) {
        return False;
    }
    if ((n % 3) == 0) {
        return False;
    }
    i = 5;
    w = 2;
    while ((i * i) <= n) {
        if ((n % i) == 0) {
            return False;
        }
        i += w;
        w = 6 - w;
    }
    return True;
}
