	"""
def radboud_colon_concepts2labels(report_concepts: dict[str, dict]) -> dict[str, dict] {
    report_labels: dict[str, dict] = dict();
    for (rid, rconcepts) in report_concepts.items() {
        report_labels[rid] = dict();
        report_labels[rid]['labels'] = {
            'cancer': 0,
            'hgd': 0,
            'lgd': 0,
            'hyperplastic': 0,
            'ni': 0
        };
        diagnosis = ' '.join(
            [concept[1].lower() for concept in rconcepts['concepts']['Diagnosis']]
        );
        if ('colon adenocarcinoma' in diagnosis) {
            report_labels[rid]['labels']['cancer'] = 1;
        }
        if ('dysplasia' in diagnosis) {
            if ('mild' in diagnosis) {
                report_labels[rid]['labels']['lgd'] = 1;
            }
            if ('moderate' in diagnosis) {
                report_labels[rid]['labels']['lgd'] = 1;
            }
            if ('severe' in diagnosis) {
                report_labels[rid]['labels']['hgd'] = 1;
            }
        }
        if ('hyperplastic polyp' in diagnosis) {
            report_labels[rid]['labels']['hyperplastic'] = 1;
        }
        label_sum = sum(list(report_labels[rid]['labels'].values()));
        if (label_sum == 0) {
            report_labels[rid]['labels']['ni'] = 1;
        }
