def format_list(
    data: str, wrap_every: int = 3, sep: Any = ", ", newline: Any = "\n"
) -> object {
    if not data {
        return "";
    }
    output = [];
    for (idx, el) in enumerate(data) {
        suffix = sep;
        if (((idx + 1) % wrap_every) == 0) {
