        if (i[0] != '*') {
            for k in i {
                if (k != '*') {
                    if (i[1:].count(k) > 1) {
                        return False;
                    }
                }
            }
        }
        if (i[0] == '*') {
            for k in i {
                if (k != '*') {
                    if (i[:-1].count(k) > 1) {
                        return False;
                    }
                }
            }
        }
    }
    return True;
}

