"""Generates a map of vector lengths from the center point to each coordinate."""
def gen_cube_vector(
    x: int,
    y: int,
    z: int,
    x_mult: int = 1,
    y_mult: int = 1,
    z_mult: int = 1
) -> list[list[list[int]]] {
