"""
Find key in the contents of a file and replace its value with the new value,
returning the resulting file. This validates that the old value is constant and
hasn't changed since parsing its value.

Raises a ValueError when the key cannot be found in the given contents.

Does not modify the value of contents.
"""
def update_key_value(
    contents: list[str], key: str, old_value: str, new_value: str
) -> list[str] {
    new_contents = contents[:];
    old_line = key + ": " + old_value;
    updated = False;
    for (line_num, line) in enumerate(new_contents) {
        if line == old_line {
            new_contents[line_num] = key + ": " + new_value;
            updated = True;
            break;
        }
    }
    if not updated {
        raise ValueError(
            "For key:%s, cannot find the old value (%s) in the given " "contents."
            % (key, old_value)
        );
    }
    return new_contents;
}

"""Format a numerical value, inserting commas as thousands separators.

  Args:
    value: An integer, float, or string representation thereof.
      If the argument is a float, it is converted to a string using '%.2f'.

  Returns:
    A string with groups of 3 digits before the decimal point (if any)
    separated by commas.

  NOTE: We don't deal with whitespace, and we don't insert
  commas into long strings of digits after the decimal point.
  """
def FormatThousands(value: int | float | str) -> str {
    text: str;
    if isinstance(value, float) {
        text = '%.2f' % value;
    } else {
        text = str(value);
    }
    head: str;
    tail: str;
    if '.' in text {
        (head, tail) = text.split('.', 1);
        tail = '.' + tail;
    } elif 'e' in text {
        (head, tail) = text.split('e', 1);
        tail = 'e' + tail;
    } else {
        head = text;
        tail = '';
    }
    sign = '';
    if head.startswith('-') {
        sign = '-';
        head = head[1:];
    }
    while len(head) > 3 {
        tail = ',' + head[-3:] + tail;
        head = head[:-3];
    }
    return sign + head + tail;
}

