            Dimensions of figure in inches
    """
def set_size(width: Any, fraction: int = 1, subplots: list = (1, 1)) -> object {
    if (width == 'thesis') {
        width_pt = 426.79135;
    } elif (width == 'beamer') {
        width_pt = 307.28987;
    } elif (width == 'pnas') {
