"""
    Sort sequence.

    Args:
        seq: the sequence of the data

    Returns:
        sequence with sorted order and no duplicates
    """
def sort_uniq(seq: list[list | str | int | float]) -> list[list | str | int | float] {
    def _check_list(x: list | str | int | float) -> bool {
        return isinstance(x, list);
    }
    seen: dict[str | int | float, int] = {};
    result: list[list | str | int | float] = [];
    for item in seq {
        marker = item;
        if _check_list(marker) {
            marker = (marker as list)[-1];
        }
        if marker in seen {
            if not _check_list(item) {
                continue;
            }
            prev = result[-1];
            if _check_list(prev) {
                lst_item = item as list;
                lst_prev = prev as list;
                lst_item.pop();
                lst_prev.pop();
                lst_prev = lst_prev + lst_item;
                lst_prev.append(marker);
                result[-1] = lst_prev;
            } else {
                result[-1] = item;
            }
            continue;
        }
        seen[marker] = 1;
        result.append(item);
    }
    return result;
}

