        "#FECB52"
    ];
    for i in range(1, (n_values + 1)) {
        colorscale.append(
            [
                (i / (n_values + 1)),
                plotly_colorscale[((i - 1) % len(plotly_colorscale))]
            ]
        );
        colorscale.append(
            [
                ((i + 1) / (n_values + 1)),
                plotly_colorscale[((i - 1) % len(plotly_colorscale))]
            ]
        );
    }
    return colorscale;
}

