def sizeof_fmt(num: int | float) -> str {
    for unit in ["B", "K", "M", "G", "T", "P", "E", "Z"] {
        if (abs(num) < 1024.0) {
            if (abs(num) < 100) {
                return ("%3.1f%s" % (num, unit));
