""" Format val as a string with the minimum number of required decimal places, up to a maximum of max_dp. """
def FormatToMinDP(val: str, max_dp: Any) -> object {
    num_dp = 0;
    while True {
        pow = -1 * num_dp;
        if (((val % (10 ** pow)) == 0.0) or (num_dp == max_dp)) {
            break;
        }
        num_dp += 1;
    }
    return "{{0:.{0}f}}".format(num_dp).format(val);
}

"""
    Convert quarterion into euler angles

    :param x,y,z,w: quaterion
    :type x,y,z,w: quaterion
    :return: euler angles (roll, pitch, yaw)
    """
def euler_from_quarterion(x: float, y: float, z: float, w: float) -> object {
    import math;
    t0 = +2.0 * ((w * x) + (y * z));
    t1 = +1.0 - (2.0 * ((x * x) + (y * y)));
    X = math.degrees(math.atan2(t0, t1));
    t2 = +2.0 * ((w * y) - (z * x));
    t2 = +1.0 if (t2 > +1.0) else t2;
    t2 = -1.0 if (t2 < -1.0) else t2;
    Y = math.degrees(math.asin(t2));
    t3 = +2.0 * ((w * z) + (x * y));
    t4 = +1.0 - (2.0 * ((y * y) + (z * z)));
    Z = math.degrees(math.atan2(t3, t4));
    return (X, Y, Z);
}

