    :param seat_str: Seat specification string
    :return: Seat ID
    """
def get_seat_id(seat_str: str) -> int {
    row = 0;
    col = 0;
    for (i, char) in enumerate(seat_str[:7]) {
        row += (char == 'B') * ((2 ** (6 - i)) as int);
    }
    for (i, char) in enumerate(seat_str[7:]) {
