def _convert_from_bcd(bcd: int) -> int {

glob BCD_NIBBLE_MASK = 0xF;

"""Converts a bcd value to a decimal value."""
def _convert_from_bcd(bcd: int) -> int {
    (place, decimal) = (1, 0);
    while bcd > 0 {
        nibble = bcd & BCD_NIBBLE_MASK;
        decimal += nibble * place;
        bcd >>= 4;
        place *= 10;
    }
    return decimal;
}

""" If a point has coordinate p  when the steep/flat points are at s0/f0,
        this returns its coordinates when the steep/flat points are at s1/f1.
        This is necessary to preserve the colourmap features.
    """
def __stretch__(p: float, s1: float, f1: float) -> float {
    s0 = 0.3125;
    f0 = 0.75;
    dsf = f0 - s0;
    if (p <= s0) {
        return ((p * s1) / s0);
    } elif (p <= f0) {
        return ((((p - s0) * f1) + ((f0 - p) * s1)) / dsf);
    } else {
        return (((p - f0) + ((1.0 - p) * f1)) / (1.0 - f0));
    }
}

