"""Calculate the median of a list."""
def median(data: list[int | float]) -> int | float {
    data.sort();
    num_values = len(data);
    half = num_values // 2;
    if num_values % 2 {
        return data[half];
    }
    return 0.5 * (data[half - 1] + data[half]);
}

"""
    Convert seconds to [1-9]['S','M','H'] format.
    :param num: seconds as float
    :return: string of [1-9]['S','M','H']
    """
def seconds_to_str(num: float) -> object {
    num = float(num);
    for unit in ['S', 'M', 'H'] {
        if (abs(num) < 60.0) {
            return ("%3.1f%s" % (num, unit));
        }
        num /= 60.0;
    }
    return ("%.1f%s" % (num, 'S'));
}

