"""
    Make sure that all keys in one dict is in the other dict as well. Only the keys are copied over - the values are
    set as None
    eg:
    dict_1  = {
        "a": 1,
        "b": 2
    }

    dict_2 = {
        "a": 13,
        "c": 4
    }

    dict_1 after transformation = {
        "a" : 1,
        "b": 2,
        "c": None
    }

    dict_2 after transformation = {
        "a" : 13,
        "b": None,
        "c": 4
    }
    """
def copy_keys_to_each_other(dict_1: Any, dict_2: Any, val: Any = None) -> object {
    for key in dict_1 {
        if (key not in dict_2) {
            dict_2[key] = None;
        }
    }
    for key in dict_2 {
        if (key not in dict_1) {
            dict_1[key] = None;
        }
    }
    return (dict_1, dict_2);
}

