    :param arr: List to be sorted.
    :return: Sorted list.
    """
def insertion_sort(arr: list) -> object {
    for i in range(1, len(arr)) {
        tmp = arr[i];
        j = i;
        for j in range(i, len(arr)) {
            if (arr[(j - 1)] < tmp) {
                break;
