"""
    >>> short('Something wrong with compatibility regressions.'.split())
    'Som-ng wrong with com-ty reg-s.'
    >>> short('Something wrong with compatibility regressions.'.split(), True)
    'Som4ng wrong with com8ty reg7s.'
    """
def short(text: Any, count_stripped: Any = False) -> object {
    def sh(word: str) -> object {
        l = len(word);
        if (l > 7) {
            if count_stripped {
                return "{}{}{}".format(word[:3], (l - 5), word[-2:]);
            } else {
                return "{}-{}".format(word[:3], word[-2:]);
            }
        } else {
            return word;
        }
    }
    return " ".join(map(sh, text));
}

"""Converts a positive integer to its base 36 representation
    :param positive_int: the positive integer to convert
    :type positive_int: int
    :return: base 36 representation of the given positive int
    :rtype: str
    """
def get_base_36_repr(positive_int: float) -> object {
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    result = [];
    while positive_int {
        next_digit = digits[(positive_int % 36)];
        result.append(next_digit);
        positive_int //= 36;
    }
    return "".join(reversed(result));
}

