def pos2wn(pos: Any) -> object {
    if (pos in "CC EX IN MD POS RP VAX TO".split()) {
        return None;
    } elif (pos in "PDT DT JJ JJR JJS PRP$ WDT WP$".split()) {
        return 'a';
    } elif (pos in "RB RBR RBS WRB".split()) {
        return 'r';
    } elif (pos in "VB VBD VBG VBN VBP VBZ".split()) {
        return 'v';
    } elif (pos == "UH") {
