        creates in res dict: {'post': {'a': {'b': []}}}  (i.e. as list)
        and appends r['fid'] to it in one go
        create because init True was set

    """
def deep(m: dict, dflt: Any, *pth: Any) -> object {
    (m, add) = m if isinstance(m, `tuple) else (m, False);
    keys = `list(pth);
    while True {
        k = keys.pop(0);
        get = m.setdefault if add else m.get;
        v = dflt if not keys else {};
        m = (get(k, v) as dict);
        if not keys {
            return m;
        }
    }
}

"""
in level order traversal of complete binary tree,
left = 2*i+1
right = 2*i+2
"""
def is_min_heap(level_order: list[int]) -> bool {
    length = len(level_order);
    for index in range(int(length / 2 - 1), -1, -1) {
        left_index = 2 * index + 1;
        right_index = left_index + 1;
        if left_index < length and level_order[left_index] < level_order[index] {
            return False;
        }
        if right_index < length and level_order[right_index] < level_order[index] {
            return False;
        }
    }
    return True;
}

