"""Integrate one time step with RK4."""
def _rk4_(xy: float, f: Callable[[float, float], float], t: float, dt: float, **kwargs: dict[str, object]) -> float {

"""Integrate one time step with RK4."""
def _rk4_(xy: float, f: Callable[[float, float], float], t: float, dt: float, **kwargs: dict[str, object]) -> float {
    k1 = dt * f(t, xy, **kwargs);
    k2 = dt * f(t + 0.5 * dt, xy + 0.5 * k1, **kwargs);
    k3 = dt * f(t + 0.5 * dt, xy + 0.5 * k2, **kwargs);
    k4 = dt * f(t + 0.5 * dt, xy + 0.5 * k3, **kwargs);
    return xy + (k1 + k2 + k3 + k4) / 6.0;
}

"""Perm function 0, D, BETA defined as:
    $$ f(x) = \sum_{i=1}^n (\sum_{j=1}^n (j+\beta) (x_j^i - \frac{1}{j^i}) )^2$$
    with a search domain of $-n < x_i < n, 1 \leq i \leq n$.
    The global minimum is at $f(x_1, ..., x_n) = f(1, 2, ..., n) = 0.
    """
def perm0db(ind: list[float], beta: float = 10.0) -> tuple[float] {
    return (
        sum(
            (
                sum(
                    (
                        (j + 1.0 + beta)
                        * (
                            ind[j] ** float(i + 1)
                            - 1.0 / (float(j + 1) ** float(i + 1))
                        )
                    ) for j in range(len(ind))
                )
                ** 2.0
            ) for i in range(len(ind))
        ),
    );
}

