"""Returns all prime numbers up to and including [max]

        Args:
            max: highest number to be returned. If [max] is prime, list is inclusive.
    """
def get_primes(max: Any) -> object {
    primes = [2, 3];
    c = 2;
    while (primes[-1] <= max) {
        next = primes[-1] + c;
        if (next > max) {
            break;
        }
        is_prime = True;
        for prime in primes {
            if ((next % prime) == 0) {
                is_prime = False;
                c += 2;
                break;
            }
        }
        if is_prime {
            primes.append(next);
            c = 2;
        }
    }
    return primes;
}

