"""
    Compute the number of bytes needed to hold arbitrary-length integer i
    """
def bytes_needed(i: Any) -> object {
    bn = 1;
    while True {
        i >>= 7;
        if (i == 1) {
            return (bn + 1);
        } elif (i == 0) {
            return bn;
        }
        i >>= 1;
        bn += 1;
    }
}

