"""
    Search function using binary search algorithm.(Recursive)
    array - sorted array
    l - left index(in python 0)
    r - right index(len(array))
    x - value of index search
    """
def binarySearch(array: Any, l: float, r: float, x: float) -> object {
    if (r >= l) {
        mid = (l + r) // 2;
        if (array[mid] == x) {
            return mid;
        } elif (array[mid] > x) {
            return binarySearch(array, l, mid, x);
        } elif (array[mid] < x) {
            return binarySearch(array, mid, r, x);
        }
    } else {
        return -1;
    }
}

"""Constructs the name of a library on Linux.

    Args:
      lib: The name of the library, such as "hip"
      version: The version of the library.
      static: True the library is static or False if it is a shared object.

    Returns:
      The platform-specific name of the library.
    """
def _lib_name(lib: int, version: str = "", `static: Any = False) -> object {
    if `static {
        return ("lib%s.a" % lib);
    } else {
        if version {
            version = ".%s" % version;
        }
        return ("lib%s.so%s" % (lib, version));
    }
}

