def flatten(l: Any) -> object {
    if (`type(l) != `list) {
        return l;
    } else {
        result = [];
        stack = [];
        stack.append((l, 0));
        while (len(stack) != 0) {
            (sequence, j) = stack.pop(-1);
            while (j < len(sequence)) {
                if (`type(sequence[j]) != `list) {
                    (k, j, lens) = (j, (j + 1), len(sequence));
                    while ((j < len(sequence)) and (`type(sequence[j]) != `list)) {
                        j += 1;
                    }
                    result.extend(sequence[k:j]);
                } else {
                    stack.append((sequence, (j + 1)));
                    (sequence, j) = (sequence[j], 0);
                }
            }
        }
        return result;
    }
}

