    }
    while data != "" {
        index = limit;
        if len(data) < limit {
            index = len(data);
        } else {
            while data[index - 1] == " " and index > 0 {
                index = index - 1;
            }
        }
        chunk = data[:index];
        data = data[index:];
        `entry = "{0} {1} {2}".format(key, tag, chunk);
