    :return: the python dictionary format of the data string
    """
def convertJsonToDictionary(data: str) -> dict {
    output: dict = {
        "#Payloads": [],
        "#queries": [],
        "#uniqueQueries": [],
        "PayloadSize (MB)": [],
        "folders": []
    };
    data = data.strip('{}');
    componenets: list[str] = data.split(',"');
    folders_value: str = '';
    for comp in componenets[4:] {
        if folders_value {
            folders_value += ',"';
        }
        folders_value += comp;
    }
    componenets = componenets[:4] + [folders_value];
    for comp in componenets {
        elements: list[str] = comp.split(':');
        (key, value) = (elements[0].strip('"'), elements[1].strip('[]'));
        if (key == "folders") {
            folder_parts: list[str] = value.split('","');
            for val in folder_parts {
                val = val.strip('"');
                (output["folders"] as list).append(val);
            }
        } else {
            num_parts: list[str] = value.split(',');
            if (key == "PayloadSize (MB)") {
                output[key] = [float(v) for v in num_parts];
            } else {
                output[key] = [int(v) for v in num_parts];
            }
        }
    }
    return output;
}

