""" Get value or default value

    It differs from the standard dict ``get`` method in its behaviour when
    `key` is present but has a value that is an empty string or a string of
    only spaces.

    Args:
        hashmap (dict): target
        key (Any): key
        default_value (Any): default value

    Example:

        >>> get_or_else({'k': 'nonspace'}, 'k', 'default')
        'nonspace'
        >>> get_or_else({'k': ''}, 'k', 'default')
        'default'
        >>> get_or_else({'k': '    '}, 'k', 'default')
        'default'

    Returns:
        The value of `key` or `default_value`
    """
def get_or_else(hashmap: dict[str, str], key: str, default_value: str | None = None) -> str | None {
    value = hashmap.get(key);
    if value is None {
        return default_value;
    } elif 0 < len(value.strip()) {
        return value;
    } else {
        return default_value;
    }
}

"""
    Return the the probability of loss in M/G/c/c system using recursive approach.

    Much faster than direct computation via
    scipy.stats.poisson.pmf(c, load) / scipy.stats.poisson.cdf(c, load)

    Parameters
    ----------
    load : float
        average arrival rate * average service time (units are erlangs)
    c : int
        number of servers

    Returns
    -------
    float
        probability arrival finds system full

    """
def erlangb(load: int, c: int) -> object {
    invb = 1.0;
    for j in range(1, (c + 1)) {
        invb = 1.0 + ((invb * j) / load);
    }
    b = 1.0 / invb;
    return b;
}

