"""
    Convert a nested dict to a flat dict with hierarchical keys
    """
def flatten(cmd: str, path: Any = "", fc: dict = {}, sep: str = ".") -> object {
    fcmd = fc.copy();
    if isinstance(cmd, `dict) {
        for (k, v) in cmd.items() {
            k = k.split(":")[1] if (":" in k) else k;
            fcmd = (flatten(v, sep.join((path, k)) if path else k, fcmd) as dict[any, any]);
        }
    } else {
        fcmd[path] = ('"' + cmd + '"') if isinstance(cmd, str) else str(cmd);
    }
    return fcmd;
}

