	"""
def divideList(x: list, k: int) -> list {
    if (k > len(x)) {
        return [[elem] for elem in x];
    }
    part_len: int = int((len(x) / k));
    parts: list = [];
    start: int = 0;
    while (start < len(x)) {
        parts.append(x[start:(start + part_len)]);
        start += part_len;
    }
