"""Subtract a dict from another"""
def subtract_dict(
    bigger: dict[str, dict | str | int | float | bool | None],
    smaller: dict[str, dict | str | int | float | bool | None],
    prefix: str = ''
) -> dict[str, dict | str | int | float | bool | None] {
    ret = bigger.copy();
    for (key, val) in smaller.items() {
        if (key not in ret) {
