"""Split a line at specific length for code blocks or
       other formatted RST sections.
    """
def split_at_linelen(line: str, length: int) -> object {
    i = int((len(line) / length));
    p = 0;
    while (i > 0) {
        p = p + length;
        while (line[p] != ' ') {
            p -= 1;
        }
        line = line[:p] + '\n' + line[(p + 1):];
        i -= 1;
    }
    return line;
}

