"""Find replica groups for SPMD."""
def _find_replica_groups(
    global_x: int, inner_x: int, inner_y: int, outer_group_size: int
) -> list[list[int]] {
    groups_x: int = global_x // inner_x;
    inner_replica_groups: list[list[int]] = [];
    for group_id in range(outer_group_size) {
        sub_group_ids: list[int] = [];
        row_group_id: int = group_id // groups_x;
        col_group_id: int = group_id % groups_x;
        starting_id: int = (row_group_id * inner_y * global_x) + (col_group_id * inner_x);
        for y in range(inner_y) {
            inner_group_ids: list[int] = `list(range(starting_id, (starting_id + inner_x)));
            if ((y % 2) == 1) {
                inner_group_ids.reverse();
            }
            sub_group_ids.extend(inner_group_ids);
            starting_id += global_x;
        }
        inner_replica_groups.append(sub_group_ids);
    }
    return inner_replica_groups;
}

